static void
load_css_once(void)
{
    static gboolean loaded = FALSE;
    if (loaded) return;
    loaded = TRUE;

    GtkCssProvider *css = gtk_css_provider_new();
    gtk_css_provider_load_from_string(css, MYFM_CSS);
    gtk_style_context_add_provider_for_display(
        gdk_display_get_default(),
        GTK_STYLE_PROVIDER(css),
        GTK_STYLE_PROVIDER_PRIORITY_APPLICATION);
    g_object_unref(css);
}


/* ═══════════════════════════════════════════
 * PREVIEW PANE
 * ═══════════════════════════════════════════ */

static void
load_text_preview(const char *path, GtkWidget *textview)
{
    const gsize CAP = 65536;
    char *buf = g_malloc(CAP);
    gssize n = -1;

    GFile *gf = g_file_new_for_path(path);
    GFileInputStream *in = g_file_read(gf, NULL, NULL);
    if (in) {
        n = g_input_stream_read(G_INPUT_STREAM(in), buf, CAP, NULL, NULL);
        g_object_unref(in);
    }
    g_object_unref(gf);

    GtkTextBuffer *tb = gtk_text_view_get_buffer(GTK_TEXT_VIEW(textview));
    if (n > 0) {
        const char *end = buf;
        if (!g_utf8_validate(buf, n, &end)) n = end - buf;
        gtk_text_buffer_set_text(tb, buf, (int)n);
    } else {
        gtk_text_buffer_set_text(tb, "(this file could not be previewed)", -1);
    }
    g_free(buf);
}

#ifdef MYFM_HAVE_POPPLER
static gboolean
render_pdf_preview(const char *path, GtkWidget *picture)
{
    GFile *gf = g_file_new_for_path(path);
    char *uri = g_file_get_uri(gf);
    g_object_unref(gf);

    GError *err = NULL;
    PopplerDocument *doc = poppler_document_new_from_file(uri, NULL, &err);
    g_free(uri);
    g_clear_error(&err);
    if (!doc) return FALSE;

    if (poppler_document_get_n_pages(doc) < 1) {
        g_object_unref(doc);
        return FALSE;
    }

    PopplerPage *page = poppler_document_get_page(doc, 0);
    double pw = 0, ph = 0;
    poppler_page_get_size(page, &pw, &ph);
    if (pw <= 0 || ph <= 0) {
        g_object_unref(page);
        g_object_unref(doc);
        return FALSE;
    }

    double scale = 480.0 / pw;
    int iw = MAX(1, (int)(pw * scale)), ih = MAX(1, (int)(ph * scale));

    cairo_surface_t *surf = cairo_image_surface_create(CAIRO_FORMAT_ARGB32, iw, ih);
    cairo_t *cr = cairo_create(surf);
    cairo_set_source_rgb(cr, 1, 1, 1);
    cairo_paint(cr);
    cairo_scale(cr, scale, scale);
    poppler_page_render(page, cr);
    cairo_destroy(cr);
    cairo_surface_flush(surf);

    /* cairo ARGB32 is premultiplied native-endian, exactly what
     * GDK_MEMORY_DEFAULT describes: no GdkPixbuf round trip needed. */
    int stride = cairo_image_surface_get_stride(surf);
    GBytes *bytes = g_bytes_new(cairo_image_surface_get_data(surf),
                                (gsize)stride * (gsize)ih);
    GdkTexture *tex = gdk_memory_texture_new(iw, ih, GDK_MEMORY_DEFAULT,
                                             bytes, (gsize)stride);
    g_bytes_unref(bytes);
    cairo_surface_destroy(surf);
    g_object_unref(page);
    g_object_unref(doc);

    gtk_picture_set_paintable(GTK_PICTURE(picture), GDK_PAINTABLE(tex));
    g_object_unref(tex);
    return TRUE;
}
#endif

/* Refreshes the preview pane to reflect the current (single-item)
 * selection.  Cheap to call often: it no-ops when the pane isn't built
 * yet or is hidden, except it still clears stale content when nothing
 * is selected. */
void
myfm_update_preview(AppState *st)
{
    if (!st->preview_stack) return;

    if (!st->preview_visible) return;

    const char *path = (st->sel_items->len == 1 &&
                         st->selected_kind == ITEM_FILE && st->selected_path)
        ? st->selected_path : NULL;

    if (!path) {
        gtk_stack_set_visible_child_name(GTK_STACK(st->preview_stack), "empty");
        gtk_label_set_text(GTK_LABEL(st->preview_title),
            st->sel_items->len > 1 ? "Multiple items selected" : "");
        gtk_label_set_text(GTK_LABEL(st->preview_meta), "");
        return;
    }

    char *base = g_path_get_basename(path);
    gtk_label_set_text(GTK_LABEL(st->preview_title), base);
    g_free(base);

    GFile *gf = g_file_new_for_path(path);
    GFileInfo *fi = g_file_query_info(gf,
        G_FILE_ATTRIBUTE_STANDARD_SIZE "," G_FILE_ATTRIBUTE_STANDARD_CONTENT_TYPE,
        G_FILE_QUERY_INFO_NONE, NULL, NULL);
    guint64 size = fi ? (guint64)g_file_info_get_size(fi) : 0;
    char *ctype = fi ? g_content_type_get_mime_type(
        g_file_info_get_content_type(fi)) : NULL;

    char *sz = format_size_short(size);
    char *meta = g_strdup_printf("%s%s%s", sz, ctype ? "   •   " : "", ctype ? ctype : "");
    gtk_label_set_text(GTK_LABEL(st->preview_meta), meta);
    g_free(sz);
    g_free(meta);

    gboolean shown = FALSE;
    if (ctype && g_str_has_prefix(ctype, "image/")) {
        gtk_picture_set_file(GTK_PICTURE(st->preview_pic), gf);
        gtk_stack_set_visible_child_name(GTK_STACK(st->preview_stack), "image");
        shown = TRUE;
    } else if (ctype && !strcmp(ctype, "application/pdf")) {
#ifdef MYFM_HAVE_POPPLER
        if (render_pdf_preview(path, st->preview_pic)) {
            gtk_stack_set_visible_child_name(GTK_STACK(st->preview_stack), "image");
            shown = TRUE;
        }
#endif
    } else if (ctype && g_str_has_prefix(ctype, "text/")) {
        load_text_preview(path, st->preview_text);
        gtk_stack_set_visible_child_name(GTK_STACK(st->preview_stack), "text");
        shown = TRUE;
    }

    if (!shown)
        gtk_stack_set_visible_child_name(GTK_STACK(st->preview_stack), "unsupported");

    g_free(ctype);
    g_clear_object(&fi);
    g_object_unref(gf);
}

void
myfm_toggle_preview(AppState *st)
{
    st->preview_visible = !st->preview_visible;
    if (st->preview_box)
        gtk_widget_set_visible(st->preview_box, st->preview_visible);
    if (st->cmd_preview) {
        if (st->preview_visible)
            gtk_widget_add_css_class(st->cmd_preview, "view-btn-active");
        else
            gtk_widget_remove_css_class(st->cmd_preview, "view-btn-active");
    }
    myfm_update_preview(st);
}

void
myfm_toggle_checkboxes(AppState *st)
{
    st->show_checkboxes = !st->show_checkboxes;
    refresh_view(st);
}

static void
on_settings_hidden_toggled(GObject *sw, GParamSpec *ps, gpointer ud)
{
    (void)ps;
    AppState *st = ud;
    gboolean active = gtk_switch_get_active(GTK_SWITCH(sw));
    if (active != st->show_hidden) {
        st->show_hidden = active;
        refresh_view(st);
    }
}

static void
on_settings_checkboxes_toggled(GObject *sw, GParamSpec *ps, gpointer ud)
{
    (void)ps;
    AppState *st = ud;
    gboolean active = gtk_switch_get_active(GTK_SWITCH(sw));
    if (active != st->show_checkboxes)
        myfm_toggle_checkboxes(st);
}

static void
on_settings_preview_toggled(GObject *sw, GParamSpec *ps, gpointer ud)
{
    (void)ps;
    AppState *st = ud;
    gboolean active = gtk_switch_get_active(GTK_SWITCH(sw));
    if (active != st->preview_visible)
        myfm_toggle_preview(st);
}

/* A small "Folder Options"-like window, mirroring the toggles Windows
 * Explorer exposes in its own Settings/Options dialog.  Changes apply to
 * the window that opened it, live, with no separate "Apply" step. */
void
myfm_open_settings(AppState *st)
{
    GtkWidget *win = gtk_window_new();
    gtk_widget_add_css_class(win, "props");
    gtk_window_set_title(GTK_WINDOW(win), "Settings");
    gtk_window_set_default_size(GTK_WINDOW(win), 420, -1);
    gtk_window_set_resizable(GTK_WINDOW(win), FALSE);
    gtk_window_set_transient_for(GTK_WINDOW(win), GTK_WINDOW(st->window));
    gtk_window_set_destroy_with_parent(GTK_WINDOW(win), TRUE);

    GtkWidget *hb = gtk_header_bar_new();
    gtk_header_bar_set_show_title_buttons(GTK_HEADER_BAR(hb), TRUE);
    gtk_window_set_titlebar(GTK_WINDOW(win), hb);

    GtkWidget *page = gtk_box_new(GTK_ORIENTATION_VERTICAL, 0);
    gtk_widget_set_margin_start(page, 22);
    gtk_widget_set_margin_end(page, 22);
    gtk_widget_set_margin_top(page, 18);
    gtk_widget_set_margin_bottom(page, 22);
    gtk_window_set_child(GTK_WINDOW(win), page);

    GtkWidget *head = gtk_label_new("Folder Options");
    gtk_widget_add_css_class(head, "prop-title");
    gtk_widget_set_halign(head, GTK_ALIGN_START);
    gtk_widget_set_margin_bottom(head, 4);
    gtk_box_append(GTK_BOX(page), head);

    GtkWidget *sub = gtk_label_new("Changes apply to this window immediately.");
    gtk_widget_add_css_class(sub, "prop-subtitle");
    gtk_widget_set_halign(sub, GTK_ALIGN_START);
    gtk_widget_set_margin_bottom(sub, 14);
    gtk_box_append(GTK_BOX(page), sub);

    gtk_box_append(GTK_BOX(page), group_title("View"));
    GtkWidget *card = card_new();

    GtkWidget *sw_hidden = gtk_switch_new();
    gtk_switch_set_active(GTK_SWITCH(sw_hidden), st->show_hidden);
    g_signal_connect(sw_hidden, "notify::active",
        G_CALLBACK(on_settings_hidden_toggled), st);
    card_add_widget(card, "Show hidden items", sw_hidden);

    GtkWidget *sw_checks = gtk_switch_new();
    gtk_switch_set_active(GTK_SWITCH(sw_checks), st->show_checkboxes);
    g_signal_connect(sw_checks, "notify::active",
        G_CALLBACK(on_settings_checkboxes_toggled), st);
    card_add_widget(card, "Item check boxes", sw_checks);

    GtkWidget *sw_preview = gtk_switch_new();
    gtk_switch_set_active(GTK_SWITCH(sw_preview), st->preview_visible);
    g_signal_connect(sw_preview, "notify::active",
        G_CALLBACK(on_settings_preview_toggled), st);
    card_add_widget(card, "Preview pane", sw_preview);

    gtk_box_append(GTK_BOX(page), card);

    gtk_window_present(GTK_WINDOW(win));
}


